mapper.select:
select oge.order_id, oge.user_avatar, oge.user_name, oge.goods_name, oge.goods_id, oge.create_time, oge.goods_spec, oge.content, oge.additional_content_time, oge.scores, oge.image, oge.explain_content, oge.update_time, oge.additional_reply_time, oge.isanonymous FROM ${database.prefix.order}hou_order_goods_evaluation oge LEFT join ${database.prefix.order}hou_order_base oob ON oge.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_goods oog ON oge.order_id = oog.order_id
and oge.common_id = #{map.commonId}
and oge.explain_content is null
and oge.shop_id = #{map.shopId}
and oge.result = #{map.resultNum}
and (oge.image is not null and oge.image !=#{map.imageNum})
group by oge.evaluation_goods_id order by oge.create_time desc

SELECT oge.evaluation_goods_id,oge.order_id,oge.user_name,oge.scores,oge.content,oge.image, oge.create_time,oge.goods_name,oge.shop_name FROM ${database.prefix.order}hou_order_goods_evaluation oge
AND oge.user_name like CONCAT('%',#{param.userName},'%')
AND oge.scores = #{param.score}
AND oge.goods_name like CONCAT('%',#{param.goodsName},'%')
AND oge.shop_name like CONCAT('%',#{param.shopName},'%')
AND oge.create_time >= #{param.startTime}
AND oge.create_time <= #{param.endTime}
order by oge.create_time desc

SELECT
ose.evaluation_id,ose.shop_id,sb.shop_name,ui.user_name,ose.order_id,
ose.evaluation_desccredit,ose.evaluation_servicecredit,ose.evaluation_deliverycredit,ose.evaluation_create_time
FROM ${database.prefix.business}hou_shop_evaluation ose
LEFT JOIN ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = ose.shop_id
LEFT JOIN ${database.prefix.userms}hou_user_info ui on ui.user_id = ose.user_id


        AND ose.evaluation_desccredit = #{param.describeScore}


        AND evaluation_servicecredit = #{param.serviceScore}


        AND ose.evaluation_deliverycredit = #{param.deliveryScore}


        AND ose.evaluation_create_time between  #{param.startTime} and #{param.endTime}


order by ose.evaluation_create_time desc

mapper.update:
update ${database.prefix.order}hou_order_goods_evaluation
set explain_content = #{param.explainContent},update_time = #{param.updateTime}
where order_id = #{param.orderId} and goods_id = #{param.goodsId}

update ${database.prefix.order}hou_order_goods_evaluation
set additional_reply_time = #{param.updateTime}
where order_id = #{param.orderId} and goods_id = #{param.goodsId}
